shell_commands.command:
cd /testbed && patch -p0 <<'PATCH'
--- tokio-util/tests/time_delay_queue.rs
+++ tokio-util/tests/time_delay_queue.rs
@@ -169,6 +169,48 @@
 }

+#[tokio::test(start_paused = true)]
+async fn remove_last_entry_wakes() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let deadline = Instant::now() + ms(5);
+    let key1 = queue.insert_at("foo", deadline);
+    let key2 = queue.insert_at("bar", deadline);
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.remove(&key1).into_inner(), "foo");
+    assert!(!queue.is_woken());
+    assert_pending!(poll!(queue));
+
+    assert_eq!(queue.remove(&key2).into_inner(), "bar");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test(start_paused = true)]
+async fn try_remove_last_entry_wakes() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let key = queue.insert("foo", ms(5));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    let entry = queue.try_remove(&key).unwrap();
+    assert_eq!(entry.into_inner(), "foo");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+
+    assert!(queue.try_remove(&key).is_none());
+    assert!(!queue.is_woken());
+}
+
